const SetValue = async (context) => {
    // Get the total months of usage
    const totalMonthsUsage = parseInt(context?.Form?.Page1?.TotalMonthsUsage?.Value || 0);

    // Get the grid and most recent StartDate
    const usageDataGrid = context?.Form?.Page1?.UsageDataGrid || [];
    const mostRecentStartDateString = usageDataGrid.length > 0 
        ? usageDataGrid[usageDataGrid.length - 1]?.StartDate?.Value || "" 
        : "";

    // Validate the most recent StartDate
    if (mostRecentStartDateString === "") {
        return "No Historical Usage Date";
    }

    const mostRecentStartDate = new Date(mostRecentStartDateString);
    if (isNaN(mostRecentStartDate)) {
        return "No Historical Usage Date";
    }

    // Calculate the missing months
    const missingMonths = 12 - totalMonthsUsage;

    // Add the missing months to the most recent StartDate
    const calculatedDate = new Date(mostRecentStartDate);
    calculatedDate.setMonth(calculatedDate.getMonth() + missingMonths);

    // Return the calculated date in mm/dd/yyyy format
    const formattedDate = `${String(calculatedDate.getMonth() + 1).padStart(2, '0')}/${String(calculatedDate.getDate()).padStart(2, '0')}/${calculatedDate.getFullYear()}`;
    return formattedDate;
};
