const SetValue = async (context) => {
    // Helper to format date as MM/DD/YYYY
    const formatDate = (dateValue) => {
        if (!dateValue) return "";

        const date = new Date(dateValue);
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const day = date.getDate().toString().padStart(2, '0');
        const year = date.getFullYear();

        return `${month}/${day}/${year}`;
    };

    const projectStage = context?.Form?.Page1?.ProjectStage?.Value || "";
    const projectStatus = context?.Form?.Page1?.ComputedProjectStatus?.Value || "";
    const projectReason = context?.Form?.Page1?.ProjectReason?.Value || "";

    // Early returns - fastest path
    if (projectReason !== "") {
        return formatDate(context?.Form?.Page1?.CanceledDate?.Value);
    }

    if (projectStatus == "Invoiced" || projectStatus.includes("Invoiced")) {
        return formatDate(context?.Form?.ContractorInformationPage?.InvoiceReceivedDate?.Value);
    }

    // Direct field access based on stage
    let dateValue = "";

    if (projectStage == "Lead") {
        dateValue = context?.Form?.Page1?.LeadAssignedDate?.Value || "";
    } else if (projectStage == "Enrollment") {
        dateValue = context?.Form?.Page1?.LeadCompletedDate?.Value || "";
    } else if (projectStage == "Assessment") {
        dateValue = context?.Form?.Page1?.EnrollmentDate?.Value || "";
    } else if (projectStage == "Installation") {
        if (projectStatus == "Installed") {
            dateValue = context?.Form?.Page1?.InstallationCompletedDate?.Value || "";
        } else {
            dateValue = context?.Form?.Page1?.AssessmentDate?.Value || "";
        }
    } else if (projectStage == "Completed") {
        dateValue = context?.Form?.Page1?.JobCompletedDate?.Value || "";
    } else {
        dateValue = context?.Form?.Page1?.LastModifiedAt?.Value || "";
    }

    return formatDate(dateValue);
};","ClearValueOnTrue":false,"ClearValueOnFalse":false,"Fields":[{"ModelKey":"Form.Page1.EnrollmentDate","FieldName":"EnrollmentDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.ProjectReason","FieldName":"ProjectReason","IsSystemModelKey":false},{"ModelKey":"Form.Page1.LastModifiedAt","FieldName":"LastModifiedAt","IsSystemModelKey":false},{"ModelKey":"Form.ContractorInformationPage.InvoiceReceivedDate","FieldName":"InvoiceReceivedDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.AssessmentDate","FieldName":"AssessmentDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.LeadCompletedDate","FieldName":"LeadCompletedDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.JobCompletedDate","FieldName":"JobCompletedDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.InstallationCompletedDate","FieldName":"InstallationCompletedDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.ProjectStage","FieldName":"ProjectStage","IsSystemModelKey":false},{"ModelKey":"Form.Page1.LeadAssignedDate","FieldName":"LeadAssignedDate","IsSystemModelKey":false},{"ModelKey":"Form.Page1.ComputedProjectStatus","FieldName":"ComputedProjectStatus","IsSystemModelKey":false},{"ModelKey":"Form.Page1.CanceledDate","FieldName":"CanceledDate","IsSystemModelKey":false}]}

