const SetValue = async (context) => {
    const startDateString = context?.Form?.StartDate?.Value || "";
    const endDateString = context?.Form?.EndDate?.Value || "";

    // Convert the date strings to Date objects
    const startDate = new Date(startDateString);
    const endDate = new Date(endDateString);

    // Check if both dates are valid
    if (isNaN(startDate) || isNaN(endDate)) {
        return "Invalid Dates"; // Return an error message if dates are invalid
    }

    // Calculate the difference in time (milliseconds)
    const differenceInTime = endDate - startDate;

    // Convert the difference from milliseconds to days
    const billingDays = differenceInTime / (1000 * 60 * 60 * 24);

    // Return the number of billing days
    return Math.round(billingDays); // Round to the nearest whole number if needed
};
